// 开关窗口
var CustomUIRoot = $.GetContextPanel().GetParent();
var sLastName = "";

function ToggleWindows(sName, func) {
	if (Game.IsShopOpen() && sName && sName.length > 0) {
		$.DispatchEvent("DOTAHUDToggleShop")
	}
	if (CustomUIRoot != null && CustomUIRoot != undefined && CustomUIRoot.IsValid()) {
		if (sName == sLastName) sName = "";
		CustomUIRoot.SwitchClass("Windows", "Show" + sName);
		sLastName = sName;
		GameUI.sOpenWindow = sName;
		if (func) {
			GameEvents.SendEventClientSide("custom_func", { name: func });
		}

	}
}
function OpenWindows(sName) {
	if (Game.IsShopOpen() && sName && sName.length > 0) {
		$.DispatchEvent("DOTAHUDToggleShop")
	}
	if (CustomUIRoot != null && CustomUIRoot != undefined && CustomUIRoot.IsValid()) {
		CustomUIRoot.SwitchClass("Windows", "Show" + sName);
		sLastName = sName;
		GameUI.sOpenWindow = sName;
	}
}
GameUI.ToggleWindows = ToggleWindows;
GameUI.OpenWindows = OpenWindows;
GameUI.CustomUIRoot = CustomUIRoot;

function CheckIsShopOpen() {
	ToggleWindows("")
}

function EmitSoundForPlayer(tData) {
	Game.EmitSound(tData.soundname);
}

function SetLanguage() {
	const lan = $.Language()
}

const tLeftClickEvt = []
const tRightClickEvt = []

// 注册鼠标左键事件
GameUI.SubLeftClick = (fun) => {
	if (typeof (fun) !== "function") {
		return
	}
	if (fun) {
		tLeftClickEvt.push(fun)
	}
}
// 注册鼠标右键事件
GameUI.SubRightClick = (fun) => {
	if (typeof (fun) !== "function") {
		return
	}
	if (fun) {
		tRightClickEvt.push(fun)
	}
}

GameUI.SetMouseCallback((eventName, value) => {
	const CONSUME_EVENT = true;
	const CONTINUE_PROCESSING_EVENT = false;

	if (GameUI.GetClickBehaviors() !== CLICK_BEHAVIORS.DOTA_CLICK_BEHAVIOR_NONE) {
		return CONTINUE_PROCESSING_EVENT;
	}

	if (eventName === "pressed" || eventName === "doublepressed" || eventName == "released") {
		switch (value) {
			case 0:
				for (const k in tLeftClickEvt) {
					const fun = tLeftClickEvt[k];
					if (fun) {
						fun(eventName)
					} else {
						delete fun
					}
				}
				break;
			case 1:
				for (const k in tRightClickEvt) {
					const fun = tRightClickEvt[k];
					if (fun) {
						fun(eventName)
					} else {
						delete fun
					}
				}
				break;
			default:
				break;
		}
	}

	return CONTINUE_PROCESSING_EVENT
});

